from typing import Any, Dict
import importlib
import inspect
import sys

from tools.base import BaseTool


class ToolExecutor:
    """Dynamically loads, instantiates, and executes tools with unified error handling."""

    def __init__(self):
        self._tool_instances: Dict[str, BaseTool] = {}

    def execute(self, tool_name: str, input_data: Dict[str, Any]) -> Dict[str, Any]:
        """Execute a tool by name with given input.

        Returns a dict with 'success' boolean and 'result' or 'error' keys.
        """
        try:
            tool_instance = self._get_tool_instance(tool_name)

            if not tool_instance:
                return {
                    'success': False,
                    'error': f"Tool not found: {tool_name}"
                }

            result = tool_instance.execute(**input_data)

            # Normalize all tool outputs to a consistent structure
            return self._normalize_result(result)

        except ImportError as e:
            return {
                'success': False,
                'error': f"Failed to import tool '{tool_name}': {e}"
            }
        except Exception as e:
            return {
                'success': False,
                'error': f"Error executing tool '{tool_name}': {e}"
            }

    def _get_tool_instance(self, tool_name: str) -> BaseTool:
        """Get or create a singleton instance of the requested tool."""
        # Clear cached module if it exists, to support 'refresh' behavior
        module_name = f'tools.{tool_name}'
        if module_name in sys.modules:
            del sys.modules[module_name]

        try:
            module = importlib.import_module(module_name)
        except ImportError:
            return None

        # Find tool class matching tool_name
        for name, obj in inspect.getmembers(module):
            if (
                inspect.isclass(obj)
                and issubclass(obj, BaseTool)
                and obj != BaseTool
            ):
                candidate = obj()
                if candidate.name == tool_name:
                    return candidate

        return None

    def _normalize_result(self, result: Any) -> Dict[str, Any]:
        """Convert any tool result into a consistent structure."""
        if isinstance(result, dict):
            if 'success' in result:
                return result
            # Wrap arbitrary dicts
            return {'success': True, 'result': result}

        if isinstance(result, (str, int, float, bool, type(None))):
            return {'success': True, 'result': result}

        # For lists, images, or other types, wrap them
        return {'success': True, 'result': result}
